/* Presentation preferences. Never modify scientific colours or arrays. */
(()=>{'use strict';const key='prostranstva-reader-v1',root=document.documentElement;let prefs={theme:'system'};try{prefs={...prefs,...JSON.parse(localStorage.getItem(key)||'{}')};}catch(_){}if(!['system','light','dark','warm'].includes(prefs.theme))prefs.theme='system';const media=matchMedia('(prefers-color-scheme: dark)');function save(){try{localStorage.setItem(key,JSON.stringify(prefs));}catch(_){}}function palette(){const s=getComputedStyle(root),get=x=>s.getPropertyValue(x).trim();return{bg:get('--reader-bg'),ink:get('--ink'),line:get('--line'),paper:get('--reader-paper')};}function apply(){root.dataset.theme=prefs.theme==='system'?(media.matches?'dark':'light'):prefs.theme;root.dataset.themePreference=prefs.theme;document.dispatchEvent(new Event('reader-theme-change'));}window.HorizonReader={palette};apply();media.addEventListener('change',()=>{if(prefs.theme==='system')apply();});
function plotTheme(){if(!window.Plotly)return;const p=palette();document.querySelectorAll('.js-plotly-plot').forEach(el=>{const u={paper_bgcolor:p.bg,plot_bgcolor:p.bg,'font.color':p.ink,'legend.bgcolor':p.paper,'legend.font.color':p.ink};if(el.layout&&el.layout.scene){u['scene.bgcolor']=p.bg;for(const a of ['xaxis','yaxis','zaxis']){u['scene.'+a+'.color']=p.ink;u['scene.'+a+'.backgroundcolor']=p.bg;u['scene.'+a+'.gridcolor']=p.line;}}Plotly.relayout(el,u);});}document.addEventListener('reader-theme-change',plotTheme);
document.addEventListener('DOMContentLoaded',()=>{const select=document.getElementById('reader-theme');if(select){select.value=prefs.theme;select.addEventListener('change',()=>{prefs.theme=select.value;save();apply();});}document.querySelectorAll('[data-reader-language]').forEach(a=>{a.addEventListener('click',()=>{prefs.language=a.dataset.readerLanguage;save();});if(location.hash)a.href+=location.hash;});let tries=0;const timer=setInterval(()=>{plotTheme();if(document.querySelector('.js-plotly-plot')||++tries>=20)clearInterval(timer);},250);});})();
